#pragma once
#include "rinkfit/joint_builder.hpp"
namespace rinkfit {
// Numerical proposal only. The caller must retain source identity/branch/widths
// and accept changes against the complete unchanged original AL objective.
struct JointQueryWitnessProposal {
 bool available=false,query_closed=false;std::array<double,3> auxiliary{};
 double native_error_sq=INFINITY,query_error_sq=INFINITY;std::size_t starts=0,closed_starts=0;
};
inline JointQueryWitnessProposal propose_joint_query_witness(const JointEventModel&model,const JointObservation&source,const std::array<double,3>&old,int subdivisions=128){
 if(source.kind==1||!source.query||subdivisions<8)throw std::runtime_error("query proposal needs a finite sliding genuine source Query");
 const auto layout=source.layout(model);auto pp=model.pointers(layout);JointObservation observation=source;observation.row=old[1];observation.alpha=old[2];JointRowEvaluation q;q.model=&model;q.layout=layout;q.observation=&observation;
 for(std::size_t k=0;k<layout.block_ids.size();++k)q.parameter_sizes[int(k)]=int(model.blocks.at(layout.block_ids[k]).values.size());
 JointQueryWitnessProposal best;
 auto closest_alpha=[&](const Vec2<double>&uv){double a=source.query->alpha.front(),z=source.query->alpha.back(),value=a,cost=INFINITY;for(int i=0;i<=32;++i){const double x=a+(z-a)*i/32.;Vec2<double>point;if(source.query->point(x,&point)){const double d=std::pow(point[0]-uv[0],2)+std::pow(point[1]-uv[1],2);if(d<cost){cost=d;value=x;}}}const double h=(z-a)/32.;a=std::max(a,value-h);z=std::min(z,value+h);for(int i=0;i<40;++i){double x=a+(z-a)*.3819660112501052,y=a+(z-a)*.6180339887498948;Vec2<double>px,py;source.query->point(x,&px);source.query->point(y,&py);double fx=std::pow(px[0]-uv[0],2)+std::pow(px[1]-uv[1],2),fy=std::pow(py[0]-uv[0],2)+std::pow(py[1]-uv[1],2);if(fx<fy)z=y;else a=x;}return .5*(a+z);};
 auto retain=[&](const std::array<double,3>&x,bool closed){if(!source.station_allowed(model,layout.path,x[0],1e-12)||x[1]<0||x[1]>1079)return;Vec2<double>query;if(!source.query->point(x[2],&query))return;const auto p=model.predict_for_al(layout,x[0],x[1],pp.data());if(!p.arithmetic_valid||p.physical_status!=DomainStatus::kValid||!model.visibility(layout,x[0],x[1],pp.data()).visible())return;for(int kind:{5,6})if(model.measurement_domain(layout,x[0],pp.data(),kind)>1e-12)return;const double rs=x[1]-p.uv[1],qe=std::pow(p.uv[0]-query[0],2)+std::pow(p.uv[1]-query[1],2)+rs*rs,ne=std::pow(p.uv[0]-source.uv[0],2)+std::pow(p.uv[1]-source.uv[1],2);const bool exact=closed&&qe<1e-12;bool improve=!best.available||(exact&&!best.query_closed)||(exact==best.query_closed&&(exact?ne<best.native_error_sq:qe<best.query_error_sq));if(improve){best.available=true;best.query_closed=exact;best.auxiliary=x;best.native_error_sq=ne;best.query_error_sq=qe;}};
 retain(old,false);
 auto attempt=[&](double station){++best.starts;const auto initial=model.predict_for_al(layout,station,source.uv[1],pp.data());if(!initial.arithmetic_valid)return;observation.row=source.uv[1];observation.alpha=closest_alpha(initial.uv);const auto nearby_root=model.project_rs(layout,station,source.uv[1]);if(nearby_root.valid){const auto nearby=model.predict_for_al(layout,station,nearby_root.row,pp.data());if(nearby.arithmetic_valid){observation.row=nearby_root.row;observation.alpha=closest_alpha(nearby.uv);retain({station,nearby_root.row,observation.alpha},false);}}std::array<double,3>x;Eigen::Matrix3d J;if(q.local_solution_uncached(pp.data(),station,&x,&J)){++best.closed_starts;const auto root=model.project_rs(layout,x[0],x[1]);if(root.valid){x[1]=root.row;retain(x,true);}}};
 attempt(old[0]);for(const auto&interval:source.station_intervals(model,layout.path))for(int i=0;i<=subdivisions;++i)attempt(interval[0]+(interval[1]-interval[0])*i/subdivisions);
 if(best.available&&!best.query_closed){for(const auto&interval:source.station_intervals(model,layout.path))if(best.auxiliary[0]>=interval[0]&&best.auxiliary[0]<=interval[1]){double lo=std::max(interval[0],best.auxiliary[0]-(interval[1]-interval[0])/subdivisions),hi=std::min(interval[1],best.auxiliary[0]+(interval[1]-interval[0])/subdivisions);auto distance=[&](double s){const auto root=model.project_rs(layout,s,source.uv[1]);if(!root.valid)return std::numeric_limits<double>::infinity();const auto p=model.predict_for_al(layout,s,root.row,pp.data());if(!p.arithmetic_valid)return std::numeric_limits<double>::infinity();const double a=closest_alpha(p.uv);Vec2<double>z;if(!source.query->point(a,&z))return std::numeric_limits<double>::infinity();retain({s,root.row,a},false);return std::pow(p.uv[0]-z[0],2)+std::pow(p.uv[1]-z[1],2);};constexpr double ratio=.6180339887498948482;double x=hi-ratio*(hi-lo),y=lo+ratio*(hi-lo),fx=distance(x),fy=distance(y);for(int k=0;k<40;++k){if(fx<fy){hi=y;y=x;fy=fx;x=hi-ratio*(hi-lo);fx=distance(x);}else{lo=x;x=y;fx=fy;y=lo+ratio*(hi-lo);fy=distance(y);}}attempt(best.auxiliary[0]);break;}}
 return best;
}
}
